 * @param departureTime
 */
export default function formatDepartureOrPickingTime(
  departureTime: string | undefined,
): string {
  // Check if WKDetail and departureTime are available
  if (departureTime) {
    // Extract date and time parts from departureTime
    const datePart = departureTime.slice(0, 10);
    const timePart = departureTime.slice(11, 19);

    // Concatenate date and time parts with a space in between
    return `${datePart} ${timePart}`;
  }
  return '';
}
