// Local imports
import type { Composer } from 'vue-i18n';
import main from './App.vue';
import { router } from './global-router/index.ts';
import { i18n } from './localization/i18n.ts';
import { getAllTranslationsByPlant } from '@/modules/downtime-screen/service/api.ts';
import { useProfileStore } from '@/modules/downtime-screen/store/user-auth-store.ts';
import { appLogger } from '@/utils/logger/app-logger.ts';
/**
 * Initializes the application by setting up necessary configurations, services, or data.
 * This function is typically called when the app starts.
 * @returns A promise that resolves when the initialization is complete.
 */
async function initializeApp(): Promise<void> {
  const pinia = createPinia();
  const app = createApp(main);
  app.use(Quasar, {
    plugins: {
      Notify,
      Loading,
    },
    config: {
      //   Notify: /* look at QuasarConfOptions from the API card */
    },
  });
  const { $q } = app.config.globalProperties;

  // Pass the Quasar instance to the NotifyPlugin
  app.use(NotifyPlugin, { $q });

  app.use(ElementPlus);
  app.use(pinia);
  pinia.use(piniaPluginPersistedstate);
  app.use(router);
  app.use(i18n);
  // Use our custom notification plugin

  app.use(mainHeader);
  app.mount('#app');
  // After app is mounted, eagerly import translations for the user's plant and merge into i18n
  try {
    const profileStore = useProfileStore();
    await profileStore.fetchUserAttributes();
    const plant = Number(profileStore.userAttributes.plant);
    if (!plant) return;

    const languages = (await getAllTranslationsByPlant(plant)) ?? {};
    // I18n.global is a Composer instance when using the Composition API
    const composer = (i18n as { global?: Composer }).global;
    for (const [lang, messages] of Object.entries(languages)) {
      const existing =
        composer && typeof composer.getLocaleMessage === 'function'
          ? composer.getLocaleMessage(lang)
          : {};
      if (composer && typeof composer.setLocaleMessage === 'function') {
        composer.setLocaleMessage(lang, {
          ...existing,
          ...messages,
        });
      }
    }
    appLogger.verbose(`Loaded translations for plant ${plant}`);
  } catch (error) {
    appLogger.warn(`Failed to load translations on startup: ${String(error)}`);
  }
}
initializeApp();

