export const getPlantById = async (id: number): Promise<Plant> => {
  const timezoneUtc = 'utc';
  const response: AxiosResponse<Plant> = await axios.get(
    `${plantHierarchyUrl}/plant/getPlantById/${id}`,
    {
      headers: {
        Authorization: `Bearer ${token}`,
      },
    },
  );
  const tz = response.data?.timezone;
  const timezone = typeof tz === 'string' && tz ? tz : timezoneUtc;
  localStorage.setItem('timezone', timezone);
  return response.data;
};
