export const getUserPreferences = async (userId: string): Promise<any> => {
  const userAttributesStore = useProfileStore();
  const plant = Number(userAttributesStore.userAttributes.plant);
  const response: AxiosResponse<
    Array<UserPreference>,
    Array<UserPreference>
  > = await axios.get(
    `${umeBaseUrl}/user-preference/${plant}/${userId}/${appName}`,
    {
      headers: {
        Authorization: `Bearer ${token}`,
      },
    },
  );
  const { data } = response;
  let columnsPreferences: UserPreference | undefined;

  const uniqueObjects: Record<string, boolean> = {};
  const filterPreferencesList: Array<UserPreference> = [];

  if (Array.isArray(data)) {
    // Start from the last index and move backwards
    const { length } = data;
    for (let index = length - 1; index >= 0; index -= 1) {
      if (data[index].action === 'HIDE_COL' && !columnsPreferences) {
        // Found the last hidden column
        columnsPreferences = data[index];
      }
      const item = data[index];
      if (item.action === 'FILTER' && typeof item.object === 'string') {
        const objectsToAdd = item.object
          .split(';')
          .filter((object) => !uniqueObjects[object]);
        for (const object of objectsToAdd) {
          uniqueObjects[object] = true;
          // Alphabetical order of keys: action, addData, appName, object, plant, user
          filterPreferencesList.unshift({
            action: item.action,
            addData: item.addData,
            appName: 'DOWNTIME-SCREEN',
            object,
            plant,
            user: { userId },
          });
        }
      }
    }
  }

  columnsPreferences ??= {
    action: 'HIDE_COL',
    addData: '',
    appName,
    object: '',
    plant,
    user: { userId },
  };

  return { columnsPreferences, filterPreferencesList };
  // Return response.data[data.length - 1];
};

