/**
 * Fetch a flat array of translations suitable for Excel export.
 * @param plant - Plant identifier to export translations for
 * @returns an array of records representing translation rows (flat shape)
 */
export const exportTranslationsForPlant = async (
  plant: number,
): Promise<Array<Record<string, unknown>>> => {
  const response: AxiosResponse<Array<Record<string, unknown>>> =
    await axios.get(
      `${downtimeBackendBaseUrl}/downtime/AllCausesTranslations`,
      {
        headers: {
          authorization: `Bearer ${token}`,
        },
        params: { plant },
      },
    );
  const data = response.data ?? [];

  const rows: Array<Record<string, unknown>> = data
    .map((row: Record<string, unknown>) => {
      const { cause } = row;
      const { sourceDesc } = row;
      const { targetLanguage } = row;
      const { translatedDesc } = row;

      return {
        cause: String(cause),
        sourceDesc: String(sourceDesc),
        targetLanguage: String(targetLanguage),
        translatedDesc: String(translatedDesc),
      };
    })
    .sort((a, b) => {
      const A = String(a.cause).toLowerCase();
      const B = String(b.cause).toLowerCase();
      if (A < B) return -1;
      if (A > B) return 1;
      return 0;
    });

  return rows;
};

/**
 * Send a bulk translations payload to the backend. The backend is expected to
 * return structured results indicating successes and errors for each row.
 * @param file - Excel File or Blob to parse and upload
 * @param plant - Plant id for which translations apply
 * @returns an object containing successCount, errorCount and errors array
 */
export const bulkAddOrUpdateTranslations = async (
  file: File | Blob,
  plant: number,
): Promise<{
  successCount: number;
  errorCount: number;
  errors: Array<{
    row: number;
    cause?: string;
    lang?: string;
    message: string;
  }>;
}> => {
  // Parse Excel file into JSON rows using ExcelJS
  const workbook = new exceljs.Workbook();
  const arrayBuffer = await file.arrayBuffer();
  await workbook.xlsx.load(arrayBuffer);
  const worksheet = workbook.worksheets[0];
  const rows: Array<Record<string, unknown>> = [];
  if (worksheet) {
    const headerRow = worksheet.getRow(1);
    const headers: Array<string> = [];
    const headerCellCount = headerRow.cellCount ?? 0;

    // Helper: safely stringify objects (handles circular refs)
    const safeStringify = (object: unknown): string => {
      try {
        const seen = new WeakSet();
        return JSON.stringify(object, (_k, v) => {
          if (typeof v === 'object' && v !== null) {
            if (seen.has(v)) return '[Circular]';
            seen.add(v);
          }
          if (typeof v === 'function') return v.toString();
          return v;
        });
      } catch {
        // As a last resort, fall back to a safe descriptor
        try {
          if (object === null || object === undefined) return '';
          if (
            typeof object === 'string' ||
            typeof object === 'number' ||
            typeof object === 'boolean'
          )
            return String(object);
          return Object.prototype.toString.call(object);
        } catch {
          return '[unserializable]';
        }
      }
    };

    for (let index = 1; index <= headerCellCount; index += 1) {
      const cell = headerRow.getCell(index);
      // Prefer the formatted text if provided by ExcelJS; otherwise fall back to value
      const hv =
        typeof cell.text === 'string' && cell.text !== ''
          ? cell.text
          : cell.value;
      if (hv === undefined || hv === null) headers.push('');
      else if (typeof hv === 'string') headers.push(hv);
      else if (typeof hv === 'number' || typeof hv === 'boolean')
        headers.push(String(hv));
      else headers.push(safeStringify(hv));
    }
    worksheet.eachRow((row, rowNumber) => {
      if (rowNumber === 1) return; // Skip header
      const object: Record<string, unknown> = {};
      for (const [index, header] of headers.entries()) {
        const key = header || `col${index + 1}`;
        const cell = row.getCell(index + 1);
        // Prefer the formatted text when available; otherwise use the raw value.
        const raw = cell.text ?? cell.value;
        let cellValue: unknown;
        if (raw === undefined || raw === null) {
          cellValue = undefined;
        } else if (typeof raw === 'string') {
          cellValue = raw;
        } else if (typeof raw === 'number' || typeof raw === 'boolean') {
          cellValue = raw;
        } else if (typeof raw === 'object') {
          cellValue = safeStringify(raw);
        } else {
          cellValue = String(raw);
        }
        object[key] = cellValue;
      }
      rows.push(object);
    });
  }

  const items = rows.map((row) => {
    const { cause } = row;
    const lang = row.targetLanguage;
    const { translatedDesc } = row;

    let isManual: boolean | undefined;
    const rawIsManual = row.isManual;
    if (rawIsManual === true) isManual = true;
    else if (rawIsManual === false) isManual = false;
    else if (typeof rawIsManual === 'string') {
      isManual = rawIsManual.trim().toLowerCase() === 'true';
    } else {
      isManual = undefined;
    }

    // Alphabetical order of keys: cause, isManual, lang, plant, translatedDesc
    return {
      cause,
      isManual,
      lang,
      plant,
      translatedDesc,
    };
  });

  const response: AxiosResponse = await axios.post(
    `${downtimeBackendBaseUrl}/downtime/translations/bulk`,
    { items },
    {
      headers: {
        authorization: `Bearer ${token}`,
      },
      params: { plant },
    },
  );

  // Expecting backend to return { successCount, errorCount, errors: [...] }
  return response.data;
};

