/**
 * Converts saved ticket-to-classify values into numeric filter codes.
 * @param values Selected ticket-to-classify values from filters or preferences.
 * @returns Unique numeric codes used by the table rows.
 */
function getTicketToClassifyCodes(values: Array<string>): Array<number> {
  const codes: Array<number> = [];

  for (const value of values) {
    if (
      (value === '1' || value.toUpperCase() === 'YES') &&
      !codes.includes(1)
    ) {
      codes.push(1);
    }

    if ((value === '0' || value.toUpperCase() === 'NO') && !codes.includes(0)) {
      codes.push(0);
    }
  }

  return codes;
}

