const useDowntimeTableStore = defineStore({
  id: 'downtimeTableStore',
  state: () => ({
    displayFilter: false,
    downtimeColumns: getDefaultDowntimeColumns(),
    downtimeFilteredColumns: [] as Array<TableColumn>,
    downtimeFilteredrows: [] as Array<TableRow>,
    plant: {} as Plant,
    plantId: getPlant(),
    rows: [] as Array<TableRow>,
    showDowntimePreferencesDialog: false,
    token: {} as Token,
    user: {} as User,
    userId: '',
  }),
  actions: {
    async getPlantById() {
      const userAttributesStore = useProfileStore();
      this.plant = await api.getPlantById(
        Number(userAttributesStore.userAttributes.plant),
      );
    },
    // Action to fetch downtime order data
    async fetchDowntimeOrderData() {
      const searchFilterStore = useFiltersStore();
      // Call the API function to get picking order data
      const classificationTableStore = useClassificationStore();
      const { resource } = classificationTableStore;

      let data: Array<TableRow>;
      const parameters = new URLSearchParams(window.location.search);
      const plant = parameters.get('plant');
      const resourceMii = parameters.get('resourceID');
      const cause = parameters.get('cause');
      const previousLink = parameters.get('previousLink');
      const startDate = parameters.get('startDate');
      const endDate = parameters.get('endDate');

      let isFromMii = 0;
      if (
        previousLink?.includes(
          'XMII/CM/SC_COMPONENTS/DASHBOARD/DMC_EPARTBOARD/V2/index.irpt',
        )
      ) {
        isFromMii = 1;
        data = await api.searchOrderBycriteria(
          resourceMii ?? '',
          undefined,
          cause ? [cause].filter((c): c is string => c !== null) : undefined,
          undefined,
          undefined,
          undefined,
          startDate
            ? DateTime.fromJSDate(new Date(startDate), {
                zone: getTimezone(),
              }).toFormat('yyyy-MM-dd HH:mm:ss')
            : undefined,
          endDate
            ? DateTime.fromJSDate(new Date(endDate), {
                zone: getTimezone(),
              }).toFormat('yyyy-MM-dd HH:mm:ss')
            : undefined,
          plant ? Number(plant) : undefined,
          isFromMii,
        );
      } else {
        data = await api.searchOrderBycriteria(
          resource,
          undefined,
          searchFilterStore.cause ? searchFilterStore.cause : undefined,
          searchFilterStore.tool ? searchFilterStore.tool : null,
          searchFilterStore.shiftCode ? searchFilterStore.shiftCode : null,
          searchFilterStore.status ? searchFilterStore.status : null,
          searchFilterStore.startDate ? searchFilterStore.startDate : null,
          searchFilterStore.endDate ? searchFilterStore.endDate : null,
        );
      }

      const threshold =
        this.plant.downtimeTicketReclassificationThreshold ??
        DEFAULT_RECLASSIFICATION_THRESHOLD;
      data = data.map((row) => {
        let effectiveDuration = 0;

        if (
          row.duration !== null &&
          row.duration !== undefined &&
          row.duration !== ''
        ) {
          effectiveDuration = Number(row.duration);
        } else if (row.startDate) {
          effectiveDuration = Math.floor(
            (Date.now() - new Date(row.startDate).getTime()) / 1000,
          );
        }

        const userId =
          row.userId ??
          ((row as unknown as Record<string, unknown>).user_id as string) ??
          '';
        const modifiedBy =
          row.modifiedBy ??
          ((row as unknown as Record<string, unknown>).modified_by as string) ??
          '';
        const isReclassifiedBySystem =
          (userId === 'TAG' || userId === 'API_NTRS') && !modifiedBy;

        return {
          ...row,
          toClassify:
            effectiveDuration > threshold && isReclassifiedBySystem ? 1 : 0,
        };
      });

      const ticketToClassifyCodes = getTicketToClassifyCodes(
        searchFilterStore.ticketToClassify,
      );

      if (ticketToClassifyCodes.length > 0) {
        data = data.filter(
          (row) =>
            typeof row.toClassify === 'number' &&
            ticketToClassifyCodes.includes(row.toClassify),
        );
      }
      data.sort((a: TableRow, b: TableRow): number => {
        const causeA = Number(a.cause);
        const causeB = Number(b.cause);

        // Ensure "Un-classified" is always at the top
        const isAUnclassified = causeA === 6;
        const isBUnclassified = causeB === 6;

        if (isAUnclassified && !isBUnclassified) {
          return -1; // "Un-classified" comes first
        }
        if (!isAUnclassified && isBUnclassified) {
          return 1; // Other causes come after "Un-classified"
        }

        if ((a.startDate ?? 0) < (b.startDate ?? 0)) {
          return 1;
        }
        if ((a.startDate ?? 0) > (b.startDate ?? 0)) {
          return -1;
        }
        if ((a.startTime ?? 0) < (b.startTime ?? 0)) {
          return 1;
        }
        if ((a.startTime ?? 0) > (b.startTime ?? 0)) {
          return -1;
        }
        return 0;
      });

      this.downtimeFilteredrows = data;
      this.rows = data;
    },
    filterTicketsForReclassification(data: Array<TableRow>): Array<TableRow> {
      const threshold =
        this.plant.downtimeTicketReclassificationThreshold ??
        DEFAULT_RECLASSIFICATION_THRESHOLD;
      const filtered = data.filter((row) => {
        const duration = Number(row.duration);
        const durationExceedsThreshold = duration > threshold;
        const userIdValue =
          row.userId ||
          ((row as unknown as Record<string, unknown>).user_id as string) ||
          '';
        const modifiedBy =
          row.modifiedBy ??
          ((row as unknown as Record<string, unknown>).modified_by as string) ??
          '';
        const isReclassifiedBySystem =
          (userIdValue === 'TAG' || userIdValue === 'API_NTRS') && !modifiedBy;

        return durationExceedsThreshold && isReclassifiedBySystem;
      });

      return filtered;
    },
    openPreferencesDialog(): void {
      this.showDowntimePreferencesDialog = true;
    },
    closePreferencesDialog(): void {
      this.showDowntimePreferencesDialog = false;
    },
    /*     SaveColumnPreferences ()  {

      localStorage.setItem('columnPreferences', JSON.stringify(this.columns));
      this.showPreferencesDialog = false;
    }, */
    filterColumns(): void {
      this.downtimeFilteredColumns = this.downtimeColumns.filter(
        (column) => column.visible,
      );
    },
    updateColumnIndexes(columnsToHide: Array<string>) {
      if (Array.isArray(columnsToHide) && columnsToHide.length > 0) {
        for (const index of columnsToHide) {
          if (index) {
            const [, name, columnIndex] = index.split('_');
            const columnList = this.downtimeColumns;
            const column = columnList.find((col) => col.name === name);
            if (column) {
              column.index = Number(columnIndex);
            }
          }
          // Reorder the columns by index
          this.downtimeColumns.sort((a, b) => a.index - b.index);
        }
      }
    },
    updateColumnsPreferences(preference: UserPreference): void {
      if (preference?.addData) {
        // Parse hidden column names from the preference addData
        const columnsToHide = preference.addData.split(';');
        const columnsToHideSet = new Set();

        // Extract just the column names from the format (removing _downtime suffix)
        for (const columnInfo of columnsToHide) {
          if (columnInfo) {
            // Handle both formats: "tool_downtime" or "tool_downtime_5"
            const columnName = columnInfo.split('_downtime')[0];
            if (columnName) {
              columnsToHideSet.add(columnName);
            }
          }
        }

        // Update visibility for all columns based on preferences
        this.downtimeColumns = this.downtimeColumns.map((column) => {
          const updatedColumn = { ...column };

          updatedColumn.visible = !columnsToHideSet.has(column.name);

          return updatedColumn;
        });

        // Update column indexes if needed
        this.updateColumnIndexes(columnsToHide);

        // Filter columns for display
        this.filterColumns();
      } else {
        // If no preferences, reset to defaults
        this.downtimeColumns = this.downtimeColumns.map((column) => {
          // Default visibility for special columns is false
          if (['tool', 'coTarget', 'status'].includes(column.name)) {
            return { ...column, visible: false };
          }
          // Default visibility for other columns is true
          return { ...column, visible: true };
        });

        // Update filtered columns
        this.filterColumns();
      }
    },
    async applyUserPreferences(): Promise<void> {
      const searchFilterStore = useFiltersStore();
      let token = import.meta.env.TOKEN;
      token =
        token === 'PING_FEDERATE' ? sessionStorage.getItem('id_token') : token;
      this.token = token;
      this.userId = localStorage.getItem('userId') || 'undefined';
      const { columnsPreferences, filterPreferencesList } =
        await api.getUserPreferences(this.userId);
      this.updateColumnsPreferences(columnsPreferences);

      // Refresh translated labels after preferences are applied
      this.updateColumnLabels();

      if (filterPreferencesList) {
        searchFilterStore.updateFilterPreferences(filterPreferencesList);
      }
    },
    resetColumnsOrder() {
      this.downtimeColumns.splice(
        0,
        this.downtimeColumns.length,
        ...getDefaultDowntimeColumns(),
      );
      this.filterColumns();
    },
    async saveColumnsPreferences(reset = false): Promise<object | null> {
      try {
        // Get hidden column names using the utility function
        const downtimeHiddenColumns = utils.getHiddenColumnNames(
          'downtime',
          this.downtimeColumns,
        );
        const hiddenColumns = `${downtimeHiddenColumns}`;

        // Create an object with the hidden column names
        const preferences: UserPreference = {
          action: 'HIDE_COL',
          addData: reset ? '' : hiddenColumns,
          appName: 'DOWNTIME-SCREEN',
          object: '',
          plant: getPlant(),
          user: {
            userId: this.userId,
          },
        };
        const prefs: Array<UserPreference> = [];
        prefs.push(preferences);
        const result = await api.saveUserPreferences([preferences]);
        this.applyUserPreferences();

        // Call the saveUserPreferences function with the preferences object
        return result;
        // ShowSaveSuccessMessage()
      } catch (error) {
        console.error('Error saving or user preferences:', error);
      }
      return null;
    },

    updateColumnLabels(): void {
      for (const column of this.downtimeColumns) {
        const labelKey = getColumnLabelKey(column.name);

        if (labelKey) {
          column.label = translate(labelKey);
        }
      }

      const userAttributesStore = useProfileStore();
      const toolColumn = this.downtimeColumns.find(
        (col) => col.name === 'tool',
      );
      if (toolColumn) {
        toolColumn.label =
          userAttributesStore.managedBy === 'PART'
            ? translate('PART')
            : translate('TOOL');
      }

      this.filterColumns();
    },

    updateToolPartColumnLabel(): void {
      this.updateColumnLabels();
    },

    async updateTickets(
      tickets: Array<TableRow>,
      newTicket: TableRow,
      filter: SearchFilters,
    ): Promise<Array<TableRow>> {
      // Check if no filter is applied (empty object or all values are falsy)
      const noFilterApplied =
        Object.keys(filter).length === 0 ||
        Object.values(filter).every(
          (value) => Array.isArray(value) && value.length === 0,
        );

      // Destructure and check if newTicket matches the filter
      const { tool, cause, status, shiftCode } = filter;
      const matchesFilter =
        (!tool?.length || tool.includes(newTicket.tool)) &&
        (!cause?.length || cause.includes(newTicket.cause?.toString())) &&
        (!status?.length || status.includes(newTicket.status)) &&
        (!shiftCode?.length ||
          shiftCode.includes(newTicket.shiftCode?.toString()));

      if (noFilterApplied || matchesFilter) {
        // Find matching ticket by cause only if the filter check passes
        const matchingTicket = tickets.find(
          (ticket) => ticket.cause === newTicket.cause,
        );
        if (matchingTicket) {
          newTicket.causeDesc = matchingTicket.causeDesc;
        }

        // If no match was found, assign a default or empty value
        if (!newTicket.causeDesc && filter.cause?.length === 0) {
          const ticketFound: Array<TicketDetails> = await api.getTicketByID(
            newTicket.resource,
            newTicket.ticket,
          );

          newTicket.causeDesc = ticketFound[0]?.causeDesc;
        }

        // Now handle updating the ticket or pushing it only if the filter is satisfied
        const index = tickets.findIndex(
          (ticket) => ticket.ticket === newTicket.ticket,
        );

        if (index === -1) {
          tickets.push(newTicket);
        } else {
          // Only update if the new ticket is newer or if updateAt is not available
          const existingTicket = tickets[index];
          const shouldUpdate =
            !existingTicket.updatedAt ||
            !newTicket.updatedAt ||
            new Date(newTicket.updatedAt) >= new Date(existingTicket.updatedAt);

          if (shouldUpdate) {
            tickets[index] = { ...tickets[index], ...newTicket };
          }
        }
      }

      return [...tickets]; // Return the updated ticket list
    },
    getters: {},
  },
});

export default useDowntimeTableStore;

import { defineStore } from 'pinia';
import { TableRow } from '../../../types/table-row-type.ts';
import { UserPreference } from '../../../types/userPreferenceType.ts';
import * as api from '../service/api.ts';
import useClassificationStore from './downtime-cause-store.ts';
import useDowntimeTableStore from './downtime-table-store.ts';
import { useProfileStore } from './user-auth-store.ts';

const useFiltersStore = defineStore({
  id: 'filters',
  state: () => ({
    cause: [] as Array<string>,
    endDate: undefined as string | undefined,
    resetSelect: false,
    rows: [] as Array<TableRow>,
    shiftCode: [] as Array<string>,
    startDate: undefined as string | undefined,
    status: [] as Array<string>,
    ticket: '' as string,
    ticketToClassify: [] as Array<string>,
    ticketToClassifyLabel: [] as Array<string>,
    tool: [] as Array<string>,
    tools: [] as Array<string>, // Adding tools state
  }),
  actions: {
    addDataToSelectedList(addData: string, selectedList: Array<string>): void {
      const addDataArray = addData.split(';');
      for (const data of addDataArray) {
        const trimmedData = data.trim();
        if (trimmedData !== '' && !selectedList.includes(trimmedData)) {
          selectedList.push(trimmedData);
        }
      }
    },

    async filterByCriteria(): Promise<Array<TableRow>> {
      const classificationTableStore = useClassificationStore();
      const { resource } = classificationTableStore;

      const data = await api.searchOrderBycriteria(
        resource,
        undefined,
        this.cause ? Object.values(this.cause) : undefined,
        this.tool ? this.tool : null,
        this.shiftCode ? this.shiftCode : null,
        this.status ? this.status : null,
        this.startDate ? this.startDate : null,
        this.endDate ? this.endDate : null,
      );

      // Extract and set unique tools
      const uniqueTools = [...new Set(data.map((row) => row.tool))].filter(
        (tool) => tool !== null,
      );
      this.tools = uniqueTools;
      return data;
    },
    resetFilter() {
      this.resetSelect = true;
      this.cause = [];
      this.ticketToClassify = [];
      this.ticketToClassifyLabel = [];
      this.tool = [];
      this.shiftCode = [];
      this.status = [];
      this.startDate = undefined;
      this.endDate = undefined;
    },
    async saveFilterPreferences(): Promise<object> {
      const downtimeStore = useDowntimeTableStore();
      downtimeStore.displayFilter = false;
      const userAttributesStore = useProfileStore();
      const plant = Number(userAttributesStore.userAttributes.plant);
      const attributes = [
        {
          attribute: `cause`,
          data: this.cause,
        },
        {
          attribute: `startDate`,
          data: [this.startDate ?? ''],
        },
        {
          attribute: `tool`,
          data: this.tool,
        },
        {
          attribute: `shiftCode`,
          data: this.shiftCode,
        },
        {
          attribute: `status`,
          data: this.status,
        },
        {
          attribute: `endDate`,
          data: [this.endDate ?? ''],
        },
        {
          attribute: `ticketToClassify`,
          data: this.ticketToClassify,
        },
      ];

      // Construct list of preferences

      const preferenceList: Array<UserPreference> = attributes.map(
        ({ attribute, data }) => ({
          action: 'FILTER',
          addData: data.join(';'),
          appName: 'DOWNTIME-SCREEN',
          object: attribute,
          plant,
          user: {
            userId: localStorage.getItem('userId') ?? '',
          },
        }),
      );

      const result = await api.saveUserPreferences(preferenceList);
      return result;
    },

    updateFilterPreferences(
      filterPreferencesList: Array<UserPreference>,
    ): void {
      for (const pref of filterPreferencesList) {
        switch (pref.object) {
          case `cause`: {
            this.addDataToSelectedList(pref.addData, this.cause);
            break;
          }
          case `startDate`: {
            this.startDate = pref.addData;
            break;
          }
          case `endDate`: {
            this.endDate = pref.addData;
            break;
          }
          case `status`: {
            this.addDataToSelectedList(pref.addData, this.status);
            break;
          }
          case `shiftCode`: {
            this.addDataToSelectedList(pref.addData, this.shiftCode);
            break;
          }
          case `tool`: {
            this.addDataToSelectedList(pref.addData, this.tool);
            break;
          }
          case `ticketToClassify`: {
            this.addDataToSelectedList(pref.addData, this.ticketToClassify);
            break;
          }
          default: {
            break;
          }
        }
      }
    },
  },
});

