export const useProfileStore = defineStore('user', {
  actions: {
    async authenticateUser() {
      const useUser = useUserStore();
      const user = await this.getUser();
      if (!user) {
        appLogger.error('User not found');
        return;
      }
      if (user) {
        const fetchedUser = await apiService.getUserByEmail(user.profile.email);
        if (fetchedUser) {
          localStorage.setItem('userId', fetchedUser.userId);
          await apiService.updateUserLastLoginByEmail(
            fetchedUser.email,
            new Date(),
          );
        } else {
          const userDetails = {
            firstName: user.profile.given_name,
            lastName: user.profile.family_name,
            email: user.profile.email,
            lastLogin: new Date(),
          };
          await apiService.saveUser(userDetails);
        }
        useUser.setProfile(
          `${user.profile.given_name} ${user.profile.family_name}`,
        );
      }
    },
    async authorizeUser() {
      const router = useRouter();
      const user = await this.getUser();
      if (user) {
        const groupNames = user.profile.groups;
        const roleNamesString = groupNames.join(',');
        const {
          isAuthorized,
          actions,
        }: {
          isAuthorized: boolean;
          actions: Array<{ actionType: string; object: string }>;
        } = await authorizeUserWithPermissions(
          apiService,
          roleNamesString,
          router,
          appBasePath,
        );

        this.isAuthorized = isAuthorized;
        this.userActions = actions || [];

        if (!isAuthorized) {
          await router.push(`${appBasePath}/unauthorized`);
        }
      } else {
        this.isAuthorized = false;
        this.userActions = [];
        await router.push(`${appBasePath}/unauthorized`);
      }
    },
    async fetchUserAttributes() {
      try {
        const attributes = await userAttributesManager.loadAttributes();
        const userAttributes =
          userAttributesManager.transformAttributesToStorageFormat(attributes);
