// Utilities to map various server search response shapes into the node shape
// Expected by the DowntimeCauseTranslation component.

/**
 * Convert a value to a trimmed string when possible.
 * Safely handles primitives and objects with common primitive-like properties.
 * @param value value to convert
 * @returns trimmed string or undefined when conversion is not possible
 */
function safeString(value: unknown): string | undefined {
  if (value === null || value === undefined) return undefined;
  if (typeof value === 'string') {
    const s = value.trim();
    return s === '' ? undefined : s;
  }
  if (typeof value === 'number' || typeof value === 'boolean')
    return String(value);
  if (typeof value === 'object') {
    const v = value as Record<string, unknown>;
    // Try common primitive-like properties if present (ensure primitive)
    const c = v.code;
    if (
      typeof c === 'string' ||
      typeof c === 'number' ||
      typeof c === 'boolean'
    )
      return String(c);
    const index = v.id;
    if (
      typeof index === 'string' ||
      typeof index === 'number' ||
      typeof index === 'boolean'
    )
      return String(index);
    const n = v.name;
    if (
      typeof n === 'string' ||
      typeof n === 'number' ||
      typeof n === 'boolean'
    )
      return String(n);
    // Fallback to JSON to avoid default '[object Object]' stringification
    try {
      return JSON.stringify(v);
    } catch {
      return undefined;
    }
  }
  return undefined;
}

/**
 * Convert a value to a safe positive number.
 * @param value numeric-like value
 * @param fallback fallback number when conversion fails
 * @returns finite positive number or fallback
 */
function safeNumber(value: unknown, fallback = 1): number {
  const n = Number(value);
  return Number.isFinite(n) && n > 0 ? n : fallback;
}

/**
 * Return true when the object already matches the DowntimeCause-like shape.
 * @param object candidate object
 * @returns true when object contains cause or cause description fields
 */
function isDowntimeCauseLike(object: Record<string, unknown>): boolean {
  return !!(object.cause ?? object['cause desc'] ?? object.causeDesc);
}

/**
 * Map a server-provided DownTimeCause-like object into the node shape.
 * @param object server object
 * @returns mapped node
 */
function mapDowntimeCauseLike(
  object: Record<string, unknown>,
): Record<string, unknown> {
  // Keep spread but list explicit keys in alphabetical order
  return {
    ...object,
    cause: object.cause ?? undefined,
    causeDesc: object.causeDesc ?? object['cause desc'] ?? undefined,
    children: undefined,
    id: object.cause,
    label: object.causeDesc ?? object['cause desc'] ?? object.cause,
    raw: object,
  };
}

/**
 * Build a top-level node using level3 data.
 * @param object original server object
 * @param level3Code optional explicit level3 code
 * @returns node built from level3
 */
function buildTopNodeFromLevel3(
  object: Record<string, unknown>,
  level3Code?: string,
): Record<string, unknown> {
  const code = level3Code ?? safeString(object.level3);
  return {
    cause: code,
    causeDesc: safeString(object.level3) ?? '',
    causeGlobal: safeNumber(object.level1Code ?? object.level1_code ?? 1) + 1,
    children: undefined,
    id: code,
    label:
      safeString(object.level3) ??
      safeString(object.level3_desc) ??
      safeString(object.level3Name) ??
      level3Code ??
      safeString(object.level2) ??
      safeString(object.level1),
    raw: object,
  };
}

/**
 * Build a top-level node using level2 data.
 * @param object original server object
 * @param level2Code optional explicit level2 code
 * @returns node built from level2
 */
function buildTopNodeFromLevel2(
  object: Record<string, unknown>,
  level2Code?: string,
): Record<string, unknown> {
  const code = level2Code ?? safeString(object.level2 ?? object.level1);
  return {
    cause: code,
    causeDesc:
      safeString(object.level2 ?? object.level2_desc ?? object.level2Name) ??
      '',
    causeGlobal: safeNumber(object.level1Code ?? object.level1_code ?? 1),
    children: undefined,
    id: code,
    label:
      safeString(object.level2) ??
      safeString(object.level2_desc) ??
      safeString(object.level2Name) ??
      level2Code ??
      safeString(object.level1),
    raw: object,
  };
}

/**
 * Build a child node from level3 data.
 * @param object original server object
 * @param level3Code optional explicit level3 code
 * @returns child node
 */
function buildChildFromLevel3(
  object: Record<string, unknown>,
  level3Code?: string,
): Record<string, unknown> {
  const code = level3Code ?? safeString(object.level3);
  return {
    cause: code,
    causeDesc: safeString(object.level3) ?? '',
    causeGlobal: safeNumber(object.level1Code ?? object.level1_code ?? 1) + 1,
    children: undefined,
    id: code,
    label:
      safeString(object.level3) ??
      safeString(object.level3_desc) ??
      safeString(object.level3Name) ??
      '',
    raw: object,
  };
}

/**
 * Map a single server result into the node shape.
 * @param object server result object
 * @returns mapped node
 */
function mapSingleResultToNode(
  object: Record<string, unknown>,
): Record<string, unknown> {
  if (isDowntimeCauseLike(object)) return mapDowntimeCauseLike(object);

  const level2CodeRaw =
    object.level2Code ?? object.level2_code ?? object.level2Id;
  const level3CodeRaw =
    object.level3Code ?? object.level3_code ?? object.level3Id;
  const level2TextRaw =
    object.level2 ?? object.level2_desc ?? object.level2Name ?? '';

  const level2Code = safeString(level2CodeRaw);
  const level3Code = safeString(level3CodeRaw);
  const level2Text = safeString(level2TextRaw) ?? '';

  const unknownLevel2 =
    ((!level2Code || String(level2Code).trim() === '') &&
      (!level2Text || String(level2Text).trim() === '')) ||
    String(level2Text).trim().toLowerCase() === 'unknown';

  if (unknownLevel2 && (object.level3 || level3Code)) {
    return buildTopNodeFromLevel3(object, level3Code);
  }

  const topNode = buildTopNodeFromLevel2(object, level2Code);

  if (object.level3 || level3Code) {
    const child = buildChildFromLevel3(object, level3Code);
    topNode.children = [child];
  }

  return topNode;
}

/**
 * Map various server search response shapes into the node shape expected
 * by the `DowntimeCauseTranslation` component.
 * @param results array of server result objects (various shapes)
 * @returns An array of node objects with keys like `cause`, `id`, `label`, optional
 * `children`, `causeDesc`, `causeGlobal`, and `raw`.
 */
export function mapServerResultsToNodes(
  results: Array<unknown>,
): Array<Record<string, unknown>> {
  if (!Array.isArray(results)) return [];
  return results.map((r) =>
    mapSingleResultToNode(r as Record<string, unknown>),
  );
}

