export const getPlant = (): number | undefined => {
  const profileStore = useProfileStore();
  const raw = profileStore.userAttributes.plant;
  const n = Number(raw);
  return Number.isFinite(n) && n !== 0 ? n : undefined;
};

/**
 * Normalize a backend bulk-upload response into a predictable shape.
 * @param result - Backend response object from a bulk translations call. May be null/undefined.
 * @returns An object containing counts for added/updated items and any errors or message returned by the backend.
 */
export function parseBulkResult(result: unknown): {
  added: number;
  updated: number;
  successCount?: number;
  errorCount?: number;
  errors?: Array<unknown>;
  message?: string;
} {
  const parsed: {
    added: number;
    updated: number;
    successCount?: number;
    errorCount?: number;
    errors?: Array<unknown>;
    message?: string;
  } = { added: 0, updated: 0 };

  if (!result || typeof result !== 'object') return parsed;
  const response = result as Record<string, unknown>;

  if (typeof response.successCount === 'number') {
    parsed.successCount = response.successCount;
    if (typeof response.errorCount === 'number')
      parsed.errorCount = response.errorCount;
  }
  if (Array.isArray(response.errors)) parsed.errors = response.errors;
  if (typeof response.added === 'number') parsed.added = response.added;
  if (typeof response.updated === 'number') parsed.updated = response.updated;

  if (!parsed.added && !parsed.updated) {
    if (typeof response.Added === 'number') parsed.added = response.Added;
    if (typeof response.Updated === 'number') parsed.updated = response.Updated;
  }
  if (typeof response.message === 'string') parsed.message = response.message;
  return parsed;
}

/**
 * Write provided rows to an Excel file and trigger a download.
 * @param rows - Array of objects representing translations (headers will be taken from object keys).
 * @param plant - Optional plant id to include in the generated filename.
 */
export function downloadRowsAsExcel(
  rows: Array<Record<string, unknown>>,
  plant?: number,
): void {
  const workbook = new exceljs.Workbook();
  const sheet = workbook.addWorksheet('Translations');

  if (Array.isArray(rows) && rows.length > 0) {
    const headers = Object.keys(rows[0]);
    sheet.addRow(headers);
    for (const r of rows) {
      sheet.addRow(
        headers.map((h) => {
          const value = r[h];
          if (value === undefined || value === null) return '';
          if (typeof value === 'string') return value;
          if (typeof value === 'number' || typeof value === 'boolean')
            return String(value);
          // For objects, attempt JSON serialization with circular-safe fallback
          try {
            const seen = new WeakSet();
            return JSON.stringify(value, (_k, v) => {
              if (typeof v === 'object' && v !== null) {
                if (seen.has(v)) return '[Circular]';
                seen.add(v);
              }
              if (typeof v === 'function') return v.toString();
              return v;
            });
          } catch {
            try {
              return Object.prototype.toString.call(value);
            } catch {
              return '[unserializable]';
            }
          }
        }),
      );
    }
  }

  const now = new Date();
  const fname = `translations_${plant ?? 'all'}_${now.getFullYear()}-${String(
    now.getMonth() + 1,
  ).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}.xlsx`;

  // Trigger download in browser by generating a buffer and using a blob
  workbook.xlsx.writeBuffer().then((buffer: ArrayBuffer) => {
    const blob = new Blob([buffer], {
      type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = fname;
    document.body.append(link);
    link.click();
    link.remove();
    URL.revokeObjectURL(link.href);
  });
}

/**
 * Validate that each row contains an allowed language code in `targetLanguage`.
 * @param rows - Array of row objects (each row may contain a `targetLanguage` property).
 * @returns A set of invalid language codes found (strings). Empty set means all rows valid.
 */
export function validateLanguageCodes(
  rows: Array<Record<string, unknown>>,
): Set<string> {
  const allowed = new Set(languages.map((l) => String(l.code).toUpperCase()));
  const invalidCodes: Set<string> = new Set();
  for (const r of rows) {
    const rawValue = r.targetLanguage;
    let code = '';
    if (typeof rawValue === 'string') code = rawValue.trim().toUpperCase();
    else if (typeof rawValue === 'number')
      code = String(rawValue).trim().toUpperCase();

    if (!code || !allowed.has(code)) {
      let asString = '(empty)';
      if (rawValue !== undefined) {
        if (typeof rawValue === 'string')
          asString = rawValue.trim() || '(empty)';
        else if (typeof rawValue === 'number') asString = String(rawValue);
        else asString = '(object)';
      }
      invalidCodes.add(asString);
    }
  }
  return invalidCodes;
}

