/**
 * Get the hidden column names for a given table.
 * @param tableName - The name of the table.
 * @param columns - The array of table columns.
 * @returns A string of hidden column names and indexes.
 */
export function getHiddenColumnNames(
  tableName: string,
  columns: Array<TableColumn>,
): string {
  const indexes = columns.map((column, index) => `id_${column.name}_${index}`);
  const hiddenColumns = columns.filter((column) => column.visible === false);
  const hiddenColumnNames = hiddenColumns.map(
    (column) => `${column.name}_${tableName}`,
  );
  const columnsPreferences = [...hiddenColumnNames, ...indexes].join(';');

  return columnsPreferences;
}

