/**
 * Checks if a specific resource ID exists within the given plants array.
 * @param plants - The array of plant objects to search through.
 * @param resourceId - The resource ID to check for existence.
 * @returns - Returns true if the resource ID exists, otherwise false.
 */
// Recursive function to search for a resourceId in the plants hierarchy
export function checkResourceIdExists(
  plants: Array<Plant>,
  resourceId: string,
): boolean {
  // Helper function to recursively search each level
  const searchResources = (
    items: Array<Plant | Uap | ProductionLine | Workcenter | Resource>,
  ): boolean => {
    for (const item of items) {
      // Check if the current item has resources (Workcenter level)
      if ('children' in item && item.children) {
        // If it's a Workcenter, we look for Resource within the children
        if ('value' in item && (item as Workcenter).children) {
          const resourceIds = (item as Workcenter).children.map(
            (resource) => resource.value,
          );
          if (resourceIds.includes(resourceId)) return true;
        }

        // If it's a UAP or ProductionLine, recurse into the children
        if ('children' in item && searchResources(item.children)) {
          return true;
        }
      }
    }
    return false;
  };

  // Start the recursive search from the top level (plants)
  return searchResources(plants);
}

/**
 * Navigates to a specific path with an optional resource ID and configurable suffix.
 * @param router - The router instance used for navigation.
 * @param router.push - Function to perform navigation.
 * @param path - The base path to navigate to.
 * @param [resourceId] - Optional resource ID to include in the path.
 * @param [fallbackPath] - Optional fallback path if resourceId is not provided.
 * @param [pathSuffix] - Optional suffix to append if resourceId exists (e.g., '/downtime-screen-details').
 */
export function goToPageWithResourceId(
  router: { push: (path: string) => void },
  path: string,
  resourceId?: string,
  fallbackPath?: string,
  pathSuffix = '',
): void {
  const targetPath = resourceId
    ? `${path}/${resourceId}${pathSuffix}`
    : (fallbackPath ?? path);

  router.push(targetPath);
}

/**
 * Checks if the specified action is allowed for the current user.
 * @param actionName - The name of the action to check.
 * @returns True if the action is allowed; otherwise, false.
 */
export function isActionAllowed(actionName: string): boolean {
  const userAuth = useProfileStore();
  const actions = userAuth.$state.userActions || [];
  return actions.some(
    (action) =>
      action.object?.toLowerCase() === actionName.toLowerCase() &&
      action.actionType?.toLowerCase() === 'enable',
  );
}

